mapper.update:
CREATE TABLE ${tableName} (
    CLIENT_KEY      VARCHAR(40)	                        NOT NULL,
    TRAFFIC_TYPE    VARCHAR(10)	    DEFAULT 'normal'    NOT NULL,
    REQ_DATE        TIMESTAMP	                        NOT NULL,
    MSG_STATUS      VARCHAR(10)	    DEFAULT 'ready'     NOT NULL,
    KISA_ORIGCODE   VARCHAR(20),
    RCS_AGENCY_ID   VARCHAR(100),
    RCS_AGENCY_KEY  VARCHAR(64),
    RCS_BRAND_KEY   VARCHAR(64),
    TEMPLATE_CODE   VARCHAR(20)	                        NOT NULL,
    CALLBACK_NUMBER VARCHAR(16),
    CAMPAIGN_ID     VARCHAR(20),
    DEPT_CODE       VARCHAR(20),
    PHONE           VARCHAR(16),
    KV_DATA         VARCHAR(4000),
    KV_DATA2        VARCHAR(4000),
    PUSH_USER_ID    VARCHAR(20),
    FILE_DATA       VARCHAR(2000),
    ROUTE_INFO      VARCHAR(20),
    SENT_DATE       TIMESTAMP,
    DONE_PRODUCT    VARCHAR(20),
    DONE_DATE       TIMESTAMP,
    DONE_CODE       VARCHAR(10),
    DONE_CODE_DESC  VARCHAR(200),
    DONE_FB_DETAIL  VARCHAR(1000),
    DONE_TELCO      VARCHAR(10),
    ETC1            VARCHAR(100),
    ETC2            VARCHAR(100),
    ETC3            VARCHAR(100),
    ETC4            VARCHAR(100),
    ETC5            VARCHAR(100),
    ETC6            VARCHAR(100),
    CONSTRAINT PK_${tableName} PRIMARY KEY (CLIENT_KEY)
);

COMMENT ON COLUMN ${tableName}.CLIENT_KEY IS        '메시지 고유 번호 (직접 고유 번호를 생성하여 입력 ex) datetime + business name + random string)';
COMMENT ON COLUMN ${tableName}.TRAFFIC_TYPE IS      '메시지 유형 - normal : 일반 (default) - real : 실시간/중요 - batch : 마케팅, 광고';
COMMENT ON COLUMN ${tableName}.REQ_DATE IS          '발송 요청 (시간 미래 시간으로 입력 시, 예약 발송됨)';
COMMENT ON COLUMN ${tableName}.MSG_STATUS IS        '발송 상태 - ready : 발송 대기 (insert 상태 값) - request : 발송 완료 - complete : 결과 수신 완료 - pre-send : select 완료 - pre-image : 이미지 등록 작업 중';
COMMENT ON COLUMN ${tableName}.KISA_ORIGCODE IS     'KISA 최초 발신사업자 구분 (코드 재판매고객은 건 별 입력, 일반 고객은 config파일에 설정한 값으로 사용)';
COMMENT ON COLUMN ${tableName}.RCS_AGENCY_ID IS     '대행사 ID ex) lguplus';
COMMENT ON COLUMN ${tableName}.RCS_AGENCY_KEY IS    '대행사 인증 Key (입력하는 agencyId가 대행사의 것일 경우, 해당 대행사의 agencyKey를 함께 전송해야 함)';
COMMENT ON COLUMN ${tableName}.RCS_BRAND_KEY IS     '발신자 인증 Key (기업에서 생성한 브랜드마다 부여되는 Key로, 메시지 전송 시 발신번호가 속한 브랜드의 Key를 함께 전송해야 함)';
COMMENT ON COLUMN ${tableName}.TEMPLATE_CODE IS     '메시지허브 템플릿 키 (허브 사용자 콘솔에 등록한 통합발송 템플릿 키)';
COMMENT ON COLUMN ${tableName}.CALLBACK_NUMBER IS   '발신번호 (문자나 RCS 발송 시 필수 입력)';
COMMENT ON COLUMN ${tableName}.CAMPAIGN_ID IS       '캠페인 ID (메시지 허브에서 캠페인 단위 통계내기위해 사용)';
COMMENT ON COLUMN ${tableName}.DEPT_CODE IS         '부서코드 (부서별 빌링이 필요한 경우 사용)';
COMMENT ON COLUMN ${tableName}.PHONE IS             '수신번호';
COMMENT ON COLUMN ${tableName}.KV_DATA IS           'Key-Value 변환데이터 (등록된 통합템플릿에 정의된 변수를 key로 하여 각 값 표기 ex) {”name”:”홍길동”, “shop”:”이마트 용산”})';
COMMENT ON COLUMN ${tableName}.KV_DATA2 IS          'Key-Value 변환데이터2 (kv_json에서 입력할 데이터가 부족할 경우 사용)';
COMMENT ON COLUMN ${tableName}.PUSH_USER_ID IS      'PUSH 앱 사용자 아이디';
COMMENT ON COLUMN ${tableName}.FILE_DATA IS         '템플릿 이미지 변경 발송 데이터 (”서비스명 . 변경할 이미지 번호 . 이미지 첨부 방식(.친구톡 이미지 Wide 여부)” key 와 값으로 이루어진 데이터 ex) {”rcs.1.path”:”pokemon.jpg”, “friendtalk.1.url.y”:”https://msghub.uplus.co.kr/image/digimon.jpg”})';
COMMENT ON COLUMN ${tableName}.ROUTE_INFO IS        '라우팅 정보 (실제 발송된 중계 및 API KEY 표기 ex) kt:a1234156, lgu:d324fdsare, dau:xxxxxxxx)';
COMMENT ON COLUMN ${tableName}.SENT_DATE IS         '발송 요청 시간 (Agent가 메시지허브 G/W 로 발송한 시간)';
COMMENT ON COLUMN ${tableName}.DONE_PRODUCT IS      '최종 발송 성공한 상품 종류';
COMMENT ON COLUMN ${tableName}.DONE_DATE IS         '단말 전달 시간 or 실패 최종 시간';
COMMENT ON COLUMN ${tableName}.DONE_CODE IS         '처리 결과 코드';
COMMENT ON COLUMN ${tableName}.DONE_CODE_DESC IS    '처리 결과 상세';
COMMENT ON COLUMN ${tableName}.DONE_FB_DETAIL IS    'fallback 발송 처리 상세 (각 채널이 발송 실패할 경우, 실패 코드와 설명 표기 ex) 첫 번째 채널이 실패하고 두 번째 채널로 발송성공할 경우, DONE_FB_DETAIL에는 첫 번째 채널의 실패 코드 및 설명 표기되며, 성공한 두 번째 채널에 대한 설명은 DONE_CODE와 DONE_CODE_DESC에 표기됨)';
COMMENT ON COLUMN ${tableName}.DONE_TELCO IS        '이통사 정보 (문자 및 RCS 발송 성공의 경우 이통사 코드 업데이트)';
COMMENT ON COLUMN ${tableName}.ETC1 IS              '기타 고객사 예비 필드1';
COMMENT ON COLUMN ${tableName}.ETC2 IS              '기타 고객사 예비 필드2';
COMMENT ON COLUMN ${tableName}.ETC3 IS              '기타 고객사 예비 필드3';
COMMENT ON COLUMN ${tableName}.ETC4 IS              '기타 고객사 예비 필드4';
COMMENT ON COLUMN ${tableName}.ETC5 IS              '기타 고객사 예비 필드5';
COMMENT ON COLUMN ${tableName}.ETC6 IS              '기타 고객사 예비 필드6';

